# IconButton IconButton Кнопки могут отображаться в нескольких размерах и цветах, могут содержать иконку. ## IconButton IconButton ## Использование Использование Компонент  `IconButton`  может содержать иконку, которая указывается напрямую через  `children` . ```tsx
import React from 'react';
import { IconButton } from '@salutejs/sdds-finai';
import { IconClose } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <IconButton>
                <IconClose color="inherit" />
            </IconButton>
        </div>
    );
}
```

## Примеры Примеры ### Размер кнопки Размер кнопки Размер кнопки задается с помощью свойства  `size` . ```tsx
import React from 'react';
import { IconButton } from '@salutejs/sdds-finai';
import { IconClose } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <IconButton size="s">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="xs">
                <IconClose color="inherit" size="xs" />
            </IconButton>
            <IconButton size="xxs">
                <IconClose color="inherit" style={{ width: '0.75rem', height: '0.75rem' }} />
            </IconButton>
        </div>
    );
}
```

### Вид кнопки Вид кнопки Вид кнопки задается с помощью свойства  `view` . Возможные значения свойства  `view` : `"default"`  – по умолчанию; `"accent"`  – акцентная; `"gradient"`  – с градиентным фоном; `"secondary"`  – вторичная; `"clear"`  – без цветового сопровождения. `"positive"`  – успешное завершение; `"warning"`  – предупреждение; `"negative"`  – ошибка; `"dark"`  – темная; `"black"`  – черная; `"white"`  – белая. ```tsx
import React from 'react';
import { IconButton } from '@salutejs/sdds-finai';
import { IconClose } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
            <IconButton size="s" view="default">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="accent">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="gradient">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="secondary">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="clear">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="positive">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="warning">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="negative">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="dark">
                <IconClose  color="inherit" />
            </IconButton>
            <IconButton size="s" view="black">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton size="s" view="white">
                <IconClose color="inherit" />
            </IconButton>
        </div>
    );
}
```

### Границы кнопки Границы кнопки Границы кнопки задаются с помощью свойства  `pin` . Возможные значения свойства  `pin` : `square`  – обычное скругление; `circle`  – сильное скругление; ```tsx
import React from 'react';
import { IconButton } from '@salutejs/sdds-finai';
import { IconClose } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
            <IconButton pin="square-square">
                <IconClose color="inherit" />
            </IconButton>
            <IconButton pin="circle-circle">
                <IconClose color="inherit" />
            </IconButton>
        </div>
    );
}
```
